/* The AI harness's command surface, built from assets/data/harness.json.
 *
 * THE LIST IS NOT TYPED HERE. harness.json is generated by
 * website/scripts/build_harness.py from claude_harness/data/commands.yaml —
 * the same file the repo's own `/mabel-help` renders, and the same file
 * `mabel.py drift` gates in both directions (a listed command with no file on
 * disk fails; a file on disk this page never mentions fails too).
 *
 * So this page cannot advertise a command the repo does not have, and cannot
 * quietly omit one it does. That is the only reason to build it this way: a
 * hand-typed list of 25 commands is correct on the day it is written.
 *
 * scripts/hxtest.py asserts the rendered cards match the JSON, that the filters
 * and the search actually filter, and that every safety badge is one the legend
 * explains.
 */
(function () {
  'use strict';
  var host = document.getElementById('ahxSurface');
  if (!host) return;

  var esc = function (s) {
    return String(s == null ? '' : s).replace(/[&<>"]/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c];
    });
  };
  /* `code spans` in the registry prose, rendered. The registry is written for a
     terminal, where backticks are just punctuation; here they should be type. */
  var ticks = function (s) {
    return esc(s).replace(/`([^`]+)`/g, '<code>$1</code>');
  };

  var SAFETY = {
    read:    { label: 'read-only', cls: 'read',
               means: 'Reads the registry or the repo. Cannot change anything.' },
    probe:   { label: 'probe', cls: 'probe',
               means: 'Opens TCP connections or runs read-only remote commands. No actuation.' },
    write:   { label: 'writes', cls: 'write',
               means: 'Writes files inside the repo. Never outside it.' },
    actuate: { label: 'can move the robot', cls: 'act',
               means: 'Needs an explicit go-ahead in the session, every time. ' +
                      'An approval given once does not carry to the next call.' }
  };

  fetch('assets/data/harness.json')
    .then(function (r) { return r.json(); })
    .then(build)
    .catch(function (e) {
      host.innerHTML = '<p class="ahx-err">Could not load the command surface.</p>';
      console.error('[harness]', e);
    });

  function build(d) {
    var all = [];
    d.groups.forEach(function (g) {
      g.commands.forEach(function (c) { all.push({ g: g, c: c }); });
    });

    var html =
      '<div class="ahx-bar">' +
        '<div class="ahx-filters" role="group" aria-label="Filter by group">' +
          '<button class="on" type="button" data-g="all">All ' +
            '<span class="ahx-n">' + d.total + '</span></button>' +
          d.groups.map(function (g) {
            return '<button type="button" data-g="' + esc(g.id) + '">' +
                     esc(g.name) + ' <span class="ahx-n">' + g.commands.length +
                   '</span></button>';
          }).join('') +
        '</div>' +
        '<label class="ahx-search">' +
          '<span class="ahx-vh">Search commands</span>' +
          '<input type="search" id="ahxQ" placeholder="search — firmware, port, tip-over…" ' +
            'autocomplete="off" spellcheck="false"/>' +
        '</label>' +
      '</div>' +
      '<p class="ahx-blurb" id="ahxBlurb"></p>' +
      '<div class="ahx-grid" id="ahxGrid"></div>' +
      '<p class="ahx-none" id="ahxNone" hidden>Nothing matches that. ' +
        'The registry is searched the same way in the repo: <code>/mabel-find &lt;term&gt;</code>.</p>';

    host.innerHTML = html;

    var grid = host.querySelector('#ahxGrid');
    var blurb = host.querySelector('#ahxBlurb');
    var none = host.querySelector('#ahxNone');
    var q = host.querySelector('#ahxQ');
    var state = { g: 'all', q: '' };

    function card(x) {
      var c = x.c, s = SAFETY[c.safety] || SAFETY.read;
      var st = c.status && c.status !== 'shipped'
        ? '<span class="ahx-badge st">' + esc(c.status) + '</span>' : '';
      return '<article class="ahx-card" data-g="' + esc(x.g.id) + '" ' +
               'data-name="' + esc(c.name) + '">' +
        '<header>' +
          '<h3><span class="ahx-slash">/</span>' + esc(c.name) +
            (c.args ? ' <span class="ahx-args">' + esc(c.args) + '</span>' : '') + '</h3>' +
          '<span class="ahx-badge ' + s.cls + '" title="' + esc(s.means) + '">' +
            esc(s.label) + '</span>' + st +
        '</header>' +
        '<p>' + ticks(c.purpose) + '</p>' +
        (c.note ? '<p class="ahx-note">' + ticks(c.note) + '</p>' : '') +
        '<footer><span class="ahx-reads">reads</span> <code>' + esc(c.reads) + '</code></footer>' +
      '</article>';
    }

    function render() {
      var shown = all.filter(function (x) {
        if (state.g !== 'all' && x.g.id !== state.g) return false;
        if (!state.q) return true;
        var hay = (x.c.name + ' ' + x.c.purpose + ' ' + x.c.reads + ' ' +
                   (x.c.args || '') + ' ' + x.g.name).toLowerCase();
        return hay.indexOf(state.q) >= 0;
      });
      grid.innerHTML = shown.map(card).join('');
      none.hidden = shown.length > 0;
      var g = d.groups.filter(function (x) { return x.id === state.g; })[0];
      blurb.textContent = g ? g.blurb
        : 'Every command is /' + d.namespace + '-<verb>, one namespace. ' +
          'Type it in Claude Code, or just ask in plain language — both reach the same registry.';
    }

    host.querySelectorAll('.ahx-filters button').forEach(function (b) {
      b.addEventListener('click', function () {
        host.querySelectorAll('.ahx-filters button').forEach(function (o) {
          o.classList.toggle('on', o === b);
        });
        state.g = b.dataset.g;
        render();
      });
    });
    q.addEventListener('input', function () {
      state.q = q.value.trim().toLowerCase();
      render();
    });

    render();

    /* the legend explains every badge the cards can actually show — written
       from the same table, so a new safety class cannot appear unexplained */
    var legend = document.getElementById('ahxLegend');
    if (legend) {
      legend.innerHTML = Object.keys(SAFETY).map(function (k) {
        return '<div><span class="ahx-badge ' + SAFETY[k].cls + '">' +
               esc(SAFETY[k].label) + '</span><p>' + esc(SAFETY[k].means) + '</p></div>';
      }).join('');
    }

    var nb = document.getElementById('ahxNotBuilt');
    if (nb && d.not_built) {
      nb.innerHTML = d.not_built.map(function (n) {
        return '<li><b>' + ticks(n.what) + '</b> ' + ticks(n.why) + '</li>';
      }).join('');
    }

    var stamp = document.getElementById('ahxStamp');
    if (stamp) {
      stamp.textContent = d.registry_commit
        ? 'Generated from ' + d.source + ' at ' + d.registry_commit
        : 'Generated from ' + d.source;
    }

    window.__ahx = { data: d, count: all.length,
                     shown: function () { return grid.children.length; } };
  }
})();
